"""
The EDIT-BASED revise — a plan reworks ONE voice in ITS sections and leaves the rest alone.

Two pure halves (the redesign, 2026-10-11):

  * `revise_arrangement` threads the plan's INSTRUCTION and PRESERVE list into the intent of
    exactly the sections it names (where its voice plays), so the regenerated voice reads the
    edit as creative direction — and reads what it must keep;
  * `splice_sections` keeps the edit surgical in the NOTES too: the voice is regenerated by its
    usual generator, but only the targeted sections' new notes replace the old; every other
    section keeps what was already accepted. (The old revise replaced the whole voice, so a fix
    to one section could silently rewrite a hook everywhere else.)

A third pure piece, `is_stalled`, is the loop's STOP RULE: the same edit asked for twice with
no gain in the judge's scores means the generator cannot act on it — another round is money
spent on the same answer (the 2026-10-11 run chased the taan's scalar runs three times).

Pure: no LLM, no I/O.
"""

from __future__ import annotations

from typing import Optional

from crew.contracts import Arrangement, Layer, Note, ProducerScores, RevisionPlan, plan_layer
from crew.generators import section_spans


def target_sections(arr: Arrangement, plan: RevisionPlan) -> list[int]:
    """The section indices the plan edits: those it names, else every section where its voice
    plays — always filtered to sections where the voice actually plays."""
    layer = plan_layer(plan)
    playing = [i for i, s in enumerate(arr.sections) if layer in s.layers]
    return [i for i in playing if i in plan.sections] if plan.sections else playing


def _directive(plan: RevisionPlan) -> str:
    keep = f" PRESERVE: {'; '.join(plan.preserve)}." if plan.preserve else ""
    return f" [REVISE — {plan.instruction}.{keep}]"


def revise_arrangement(arr: Arrangement, plan: RevisionPlan) -> Arrangement:
    """A COPY of the chart with the plan's directive appended to the intent of each targeted
    section, so re-running that voice's generator reads it as creative intent. Pure."""
    revised = arr.model_copy(deep=True)
    for index in target_sections(arr, plan):
        section = revised.sections[index]
        section.intent = (section.intent or "") + _directive(plan)
    return revised


def _windows(arr: Arrangement, indices: list[int]) -> list[tuple[float, float]]:
    return [(span.start, span.end) for span in section_spans(arr) if span.index in indices]


def _inside(note: Note, windows: list[tuple[float, float]]) -> bool:
    return any(start <= note.start < end for start, end in windows)


def _spliced(old: Optional[Layer], new: Optional[Layer],
             windows: list[tuple[float, float]]) -> Optional[Layer]:
    """One layer: the old notes outside the windows + the new notes inside them."""
    base = new or old
    if base is None:
        return None
    kept = [n for n in (old.notes or []) if not _inside(n, windows)] if old else []
    fresh = [n for n in (new.notes or []) if _inside(n, windows)] if new else []
    notes = sorted(kept + fresh, key=lambda n: n.start)
    return base.model_copy(update={"notes": notes}) if notes else None


def splice_layer(arr: Arrangement, plan: RevisionPlan, old: Optional[Layer],
                 new: Optional[Layer]) -> Optional[Layer]:
    """A single-layer voice (the riff) after the edit: new notes only in the targeted sections."""
    return _spliced(old, new, _windows(arr, target_sections(arr, plan)))


def splice_layers(arr: Arrangement, plan: RevisionPlan, old: list[Layer],
                  new: list[Layer]) -> list[Layer]:
    """A multi-layer voice (the lead's sitar + lead guitar, the orchestra's families) after the
    edit, matched by role + instrument: new notes only in the targeted sections."""
    windows = _windows(arr, target_sections(arr, plan))
    key = lambda layer: (layer.role, layer.instrument)  # noqa: E731
    old_by, new_by = {key(x): x for x in old}, {key(x): x for x in new}
    order = list(dict.fromkeys([*old_by, *new_by]))
    out = [_spliced(old_by.get(k), new_by.get(k), windows) for k in order]
    return [layer for layer in out if layer is not None]


def plan_target(arr: Arrangement, plan: RevisionPlan) -> tuple[str, tuple[int, ...]]:
    """What a plan edits — its voice and the sections it actually lands in. Two plans with the
    same target ask for the same edit, whatever their wording. Pure."""
    return plan.voice, tuple(target_sections(arr, plan))


def mean_score(scores: ProducerScores) -> float:
    """The Producer's rubric mean — the one number the stop rule compares. Pure."""
    values = list(scores.model_dump().values())
    return sum(values) / len(values)


def is_stalled(arr: Arrangement, previous: RevisionPlan | None, previous_scores: ProducerScores | None,
               plan: RevisionPlan, scores: ProducerScores) -> bool:
    """True when the judge asks for the SAME edit it asked for last round and the revise did not
    raise its scores — the generator could not act on the instruction, so accept rather than pay
    for the same answer again. A first plan, a new target, or any gain keeps the loop going. Pure."""
    if previous is None or previous_scores is None:
        return False
    if plan_target(arr, plan) != plan_target(arr, previous):
        return False
    return mean_score(scores) <= mean_score(previous_scores)
